const requestRetry = () => {
    const requestedOwner = owner
    const args: ScopedUiControlArgs = {
      action: 'control',
      scope: 'group-dialog',
      target: group.id,
      operation: 'retry-preview',
      payload: { owner: requestedOwner, revision: revisionRef.current }
    }
    void requestUiControl(context, args).then((result) => {
      if (ownerRef.current !== requestedOwner) return
      if (!isGroupControlResult(result, args)) throw new Error('The window returned no UI control result.')
      if (result.delivered === 0) context.log('worktree: retry-preview reached no mounted target')
    }).catch((error: unknown) => {
      if (ownerRef.current !== requestedOwner) return
      context.toast('Could not update section dialog', messageOf(error))
    })
  }

export async function requestUiControl(context: UiPluginContext, args: UiControlArgs): Promise<UiControlResult> {
  const connId = await currentWindowId(context)
  const request = uiControlRequest(args)
  const reply = await context.call('ui.window.command.run', {
    connId,
    id: request.command,
    args: request.args
  })
  if (typeof reply !== 'object' || reply === null || Array.isArray(reply) || !('result' in reply)) {
    throw new Error('The window returned no UI control result.')
  }
  const result = reply.result
  if (typeof result !== 'object' || result === null || Array.isArray(result) || !('delivered' in result) || typeof result.delivered !== 'number') {
    throw new Error('The window returned no UI control result.')
  }
  return result as unknown as UiControlResult
}

function uiControlRequest(args: UiControlArgs): { command: typeof UI_CONTROL_COMMAND; args: UiControlArgs } {
  return { command: UI_CONTROL_COMMAND, args }
}

const remove = async () => {
    const current = previewRef.current
    if (ownerRef.current !== owner || current.owner !== owner || current.status !== 'ready' || busyRef.current || pendingRef.current) return
    const operationOwner = owner
    busyRef.current = true
    setBusy(true)
    const expectedLedgers = expectedLedgerSnapshots(current.preview)
    const ok = await changeGroup(context, 'Could not delete section', () => context.call('quirky.repo/groupDelete', {
      group: group.id,
      ...(expectedLedgers === undefined ? {} : { expectedLedgers })
    }))
    if (ownerRef.current !== operationOwner) return
    busyRef.current = false
    setBusy(false)
    if (ok) onClose()
    else runPreview()
  }

