const save = async () => {
    if (busyRef.current) return
    const submitted = draftRef.current.map((row) => ({ ...row.status }))
    if (submitted.some((status) => status.icon !== undefined && !isSafeIcon(status.icon))) {
      context.toast('Invalid status icon', 'Use plain-text emoji or symbols; URLs, SVG and HTML are not allowed.')
      return
    }

    const requestContext = context
    const mounted = registration.current
    if (!mounted || !currentRegistration(mounted)) return
    busyRef.current = true
    const operation = ++busyOperation.current
    setBusy(true)
    try {
      const saved: unknown = await requestContext.call('quirky.worktree/setStatusDefinitions', { statuses: submitted })
      if (!currentRegistration(mounted) || busyOperation.current !== operation) return
      if (!Array.isArray(saved)) throw new Error('The workspace status owner returned an invalid result.')
      savedCallback.current(saved as WorktreeStatusDefinition[])
    } catch (error) {
      if (!currentRegistration(mounted) || busyOperation.current !== operation) return
      requestContext.toast('Could not save workspace statuses', errorMessage(error))
      busyRef.current = false
      setBusy(false)
    }
  }

const create = async () => {
    const submittedQuery = queryRef.current
    const name = submittedQuery.trim()
    if (name === '') return
    const lease = startMutation()
    if (!lease) return
    try {
      const created = await createTag(lease.context, name)
      if (!created || !mutationIsCurrent(lease)) return
      if (queryRef.current === submittedQuery) {
        queryRef.current = ''
        setQuery('')
      }
      const assigned = await assignTag(lease.context, lease.worktreeIds, created.id, true)
      if (!mutationIsCurrent(lease)) return
      if (assigned) await load()
    } finally {
      finishMutation(lease)
    }
  }

export async function createTag(context: UiPluginContext, name: string, color?: TagColor | null): Promise<Tag | null> {
  try {
    const result = (await context.call('quirky.worktree/tagCreate', { name, ...(color === undefined ? {} : { color }) })) as { tag: Tag }
    return result.tag
  } catch (error) {
    context.toast('Could not create tag', messageOf(error))
    return null
  }
}

